const citas = $input.all();

if (citas.length === 0) {
  return [{
    json: {
      mensaje: "No tienes citas agendadas actualmente. 🐾\n\n¿En qué más puedo ayudarte?\n\n1️⃣ Agendar cita\n2️⃣ Ver mis citas\n3️⃣ Cancelar una cita\n4️⃣ Información de la veterinaria\n5️⃣ Hablar con alguien del equipo"
    }
  }];
}

const listado = citas.map((cita, index) => {
  const fecha = new Date(cita.json.fecha_hora);
  const fechaLegible = fecha.toLocaleDateString('es-PE', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });

  return `${index + 1}. 🐾 ${cita.json.mascota}
   🩺 ${cita.json.servicio}
   📅 ${fechaLegible}
   Estado: ${cita.json.estado_cita}`;
}).join('\n\n');

return [{
  json: {
    mensaje: `Tus citas próximas 📋\n\n${listado}`
  }
}];

