const raw = $input.first().json.text;

const cleaned = raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let respuesta, intencion, datos;

try {
  const fixedJson = cleaned.replace(/:\s*"([\s\S]*?)"/g, (match, p1) => {
    const fixed = p1.replace(/\n/g, '\\n').replace(/\r/g, '');
    return `: "${fixed}"`;
  });
  const parsed = JSON.parse(fixedJson);
  const data = parsed.output || parsed;
  respuesta = data.respuesta;
  intencion = data.intencion;
  datos = data.datos || {};
} catch(e) {
  respuesta = "Por favor elige un número válido del listado.";
  intencion = "cancelacion_invalida";
  datos = {};
}

return [{
  json: { respuesta, intencion, datos }
}];

// Fecha actual en Lima (UTC-5)
const ahoraUTC = new Date();
const offsetMs = -5 * 60 * 60 * 1000;
const ahoraLima = new Date(ahoraUTC.getTime() + offsetMs);

const pad = (n) => String(n).padStart(2, '0');

const yyyy = ahoraLima.getUTCFullYear();
const mm   = pad(ahoraLima.getUTCMonth() + 1);
const dd   = pad(ahoraLima.getUTCDate());
const hh   = pad(ahoraLima.getUTCHours());
const min  = pad(ahoraLima.getUTCMinutes());
const ss   = pad(ahoraLima.getUTCSeconds());

const fecha_hoy   = `${yyyy}-${mm}-${dd}`;
const hora_actual = `${hh}:${min}:${ss}`;

const diasNombre = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const nombre_hoy = diasNombre[ahoraLima.getUTCDay()];

// Calcula la próxima ocurrencia de un día (0=dom, 1=lun ... 6=sáb) desde mañana
function proximoDia(targetWeekday) {
  let cursor = new Date(ahoraLima.getTime());
  cursor.setUTCDate(cursor.getUTCDate() + 1); // empieza desde mañana
  while (cursor.getUTCDay() !== targetWeekday) {
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }
  const y = cursor.getUTCFullYear();
  const m = pad(cursor.getUTCMonth() + 1);
  const d = pad(cursor.getUTCDate());
  return `${y}-${m}-${d}`;
}

const mananaDate = new Date(ahoraLima.getTime());
mananaDate.setUTCDate(mananaDate.getUTCDate() + 1);
const manana = `${mananaDate.getUTCFullYear()}-${pad(mananaDate.getUTCMonth()+1)}-${pad(mananaDate.getUTCDate())}`;

return [{
  json: {
    fecha_hoy,
    hora_actual,
    nombre_hoy,
    manana,
    proximo_lunes:     proximoDia(1),
    proximo_martes:    proximoDia(2),
    proximo_miercoles: proximoDia(3),
    proximo_jueves:    proximoDia(4),
    proximo_viernes:   proximoDia(5),
    proximo_sabado:    proximoDia(6),
  }
}];

const mensaje = $('Telegram Trigger').first().json.message.text;

// Extrae solo los números del mensaje (ignora espacios, guiones o el símbolo +)
let numeros = mensaje.replace(/\D/g, '');

// Si el usuario incluyó el código de país de Perú (51) y el total son 11 dígitos, lo quitamos
if (numeros.length === 11 && numeros.startsWith('51')) {
  numeros = numeros.substring(2);
}

let respuesta, intencion, telefono;

// Validación estricta: Exactamente 9 dígitos y debe empezar con 9
if (numeros.length === 9 && numeros.startsWith('9')) {
  intencion = "telefono_valido";
  telefono = numeros;
  respuesta = "¡Gracias! Ahora, para iniciar el agendamiento 🐾\n¿Cómo se llama tu mascota y qué tipo de animal es? \nEjemplo: 'Se llama Monchi y es una gata' o 'Tengo un perro que se llama Max'";
} else {
  intencion = "telefono_invalido";
  telefono = null;
  respuesta = "Hmm, ese no parece un celular válido. 🤔 Por favor, escríbeme tu número de 9 dígitos (ejemplo: 989898989) para poder contactarte.";
}

return [{
  json: { respuesta, intencion, telefono }
}];

